select t.process_order_id, t.order_id, t.warning_order_id, t.send_type, t.send_order_time, t.process_order_time,
t.process_id, t.curren_area_id, t.air_runing, t.process_opinion, t.process_img, t.process_video,
t.order_status, t.modifier_date, t.delete_flag,t.ext1
from vm_process_order_t t


        and t.process_order_id = #{processOrderId}


        and t.process_id = #{processId}

    and t.order_id = #{warningOrderId}
    AND t.delete_flag = '0'

order by t.send_order_time desc limit 1

select t.process_order_id, t.order_id, t.warning_order_id, t.send_type, t.send_order_time, t.process_order_time,
t.process_id, t.curren_area_id, t.air_runing, t.process_opinion, t.process_img, t.process_video,
t.order_status, t.modifier_date, t.delete_flag,t.ext1
from vm_process_order_t t


        and t.process_order_id = #{processOrderId}


        and t.process_id = #{processId}

    and t.order_id = #{warningOrderId}
    AND t.delete_flag = '0' and order_status='0'

order by t.send_order_time desc limit 1

