update vm_process_order_t set
process_order_id=#{processOrderId,jdbcType=VARCHAR}
,modifier_date = now()

    ,air_runing = #{airRuning,jdbcType=VARCHAR}


    ,process_opinion = #{processOpinion,jdbcType=VARCHAR}


    ,process_img = #{processImg,jdbcType=VARCHAR}


    ,process_video = #{processVideo,jdbcType=VARCHAR}


    ,delete_flag = #{deleteFlag,jdbcType=VARCHAR}


    , order_status = #{ orderStatus,jdbcType=VARCHAR}


    , process_id = #{processId,jdbcType=VARCHAR}


    , voice = #{voice,jdbcType=VARCHAR}


    , ext1 = #{ext1,jdbcType=VARCHAR}

,process_order_time = now()
where process_order_id = #{processOrderId}

    and order_id = #{orderId}
